// KeygenGenerateLocal generates a new SSH key pair entirely on this device.
//
// Inputs:
//   - cKeyType   : "ed25519" | "rsa-4096" | "ecdsa-p256"
//   - cComment   : optional comment appended to the public key
//   - cPassphrase: optional; encrypts the private key with bcrypt-pbkdf
//
// Returns JSON with the full KeyPair (public + private + fingerprint).
// Caller MUST call CoreFreeString on the return value.
//
extern char* KeygenGenerateLocal(char* cKeyType, char* cComment, char* cPassphrase);

// KeygenInjectPublicKeyCmd builds an idempotent shell command that appends
// the public key to ~/.ssh/authorized_keys (creating directories with the
// correct permissions if needed). The command prints "INJECT_OK:..." or
// "INJECT_FAIL:..." so the caller can determine outcome from the SSH
// response without re-fetching state.
//
// Inputs:
//   - cHome     : absolute path to the target user's home directory
//   - cPublicKey: full OpenSSH single-line public key
//
// Returns JSON: {"command": "..."}.
//
extern char* KeygenInjectPublicKeyCmd(char* cHome, char* cPublicKey);

// KeygenVerifyKeyInjectedCmd builds a shell command that prints "VERIFY_OK"
// if the given public key is currently present in authorized_keys, or
// "VERIFY_MISSING" otherwise.
//
extern char* KeygenVerifyKeyInjectedCmd(char* cHome, char* cPublicKey);

// KeygenRemoveKeyByFingerprintCmd builds a shell command that removes every
// authorized_keys entry matching the given SHA256 fingerprint. Server-side
// match uses ssh-keygen -lf so comment manipulation cannot cause false
// matches.
//
extern char* KeygenRemoveKeyByFingerprintCmd(char* cHome, char* cFingerprint);

