// delimiters that ParseAllKeys understands.
//
extern char* KeygenListAllKeysCmd(char* cHome);

// KeygenParseAllKeys parses the output of ListAllKeysCmd into a structured
// list of AuthorizedKey entries (one per public key encountered).
//
// Returns JSON: {"keys": [...]} — the slice is always present, never null.
//
extern char* KeygenParseAllKeys(char* cOutput);

// KeygenSSHPortDetectCmd builds a shell command that probes three sources
