// caller can see which probe answered.
//
// configPath defaults to /etc/ssh/sshd_config when empty.
//
extern char* KeygenSSHPortDetectCmd(char* cConfigPath);

// KeygenSSHPortParse parses the output of SSHPortDetectCmd. The result
// includes the detected port, the probe that supplied it, and the raw
// output line for diagnostics.
//
// Returns JSON: {"port": int, "method": string, "raw": string}.
//
extern char* KeygenSSHPortParse(char* cOutput);

// KeygenFingerprint computes the SHA256 fingerprint of an OpenSSH-format
// public key line. Returns an empty string if the line cannot be parsed.
// Useful for de-duplicating keys client-side without round-tripping to the
// server.
//
extern char* KeygenFingerprint(char* cPublicKeyLine);

// KeygenTestExecute performs an ephemeral SSH session against an UNREGISTERED
// server (no CAT) — connects with the supplied credentials, runs a single
// command, and disconnects. Designed for the Add-Server wizard's "Generate
// & Inject" flow, where the public-key injection must run before the server
// is persisted.
//
// Inputs match SSHTestConnect plus a command string. If both privateKey and
// password are provided, the SSH client tries privateKey first (matching
// the production connect path).
//
// Returns the same JSON shape as SSHExecute:
//
//	{"success":true,"data":{"stdout":"...","stderr":"...","exit_code":0}}
//
extern char* KeygenTestExecute(char* cHost, int cPort, char* cUsername, char* cPassword, char* cPrivateKey, char* cPassphrase, char* cCommand);

