// SecureInstallPlugin performs the full blind relay installation.
//
// Two modes (auto-selected):
//
// Server-Direct (preferred — datacenter speeds):
//   Server downloads encrypted binary directly from backend via curl.
//   Mac only relays tiny metadata tokens (~2KB) via SSH.
//
// Legacy Relay (fallback — when server can't reach backend):
//   Mac downloads encrypted binary from backend, uploads to server via SSH.
//   Slower but works even when server has no outbound internet.
//
extern char* SecureInstallPlugin(char* cServerID, char* cSlug, char* cBaseURL, char* cToken, char* cLicenseToken, char* cTokenSignature, char* cNonce, char* cFingerprint, char* cProgressID);

